use vectors::*;

use std::cmp::Ordering;

use chrono::FixedOffset;
use pi_js::intl;
use pretty_assertions::assert_eq;

#[test]
fn number_to_locale_string_matches_node() {
    let mut failures = Vec::new();
    for &(bits, expected) in NUMBERS {
        let n = f64::from_bits(bits);
        let got = intl::number_to_locale_string(n);
        if got != expected {
            failures.push(format!("{n:e} ({bits:#018x}): expected {expected:?}, got {got:?}"));
        }
    }
    assert!(
        failures.is_empty(),
        "{} mismatches:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn locale_compare_sort_matches_node() {
    let mut idx: Vec<usize> = (0..COLLATE_WORDS.len()).collect();
    idx.sort_by(|&a, &b| intl::locale_compare(COLLATE_WORDS[a], COLLATE_WORDS[b]));
    let got: Vec<&str> = idx.iter().map(|&i| COLLATE_WORDS[i]).collect();
    let expected: Vec<&str> = COLLATE_SORTED.iter().map(|&i| COLLATE_WORDS[i]).collect();
    assert_eq!(got, expected);
}

#[test]
fn locale_compare_pairs_match_node() {
    let mut failures = Vec::new();
    for &(a, b, sign) in COLLATE_PAIRS {
        let expected = match sign {
            -1 => Ordering::Less,
            0 => Ordering::Equal,
            _ => Ordering::Greater,
        };
        let got = intl::locale_compare(COLLATE_WORDS[a], COLLATE_WORDS[b]);
        if got != expected {
            failures.push(format!(
                "{:?} vs {:?}: expected {expected:?}, got {got:?}",
                COLLATE_WORDS[a], COLLATE_WORDS[b]
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} mismatches:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn locale_compare_basics() {
    assert_eq!(intl::locale_compare("a", "B"), Ordering::Less);
    assert_eq!(intl::locale_compare("a", "A"), Ordering::Less);
    assert_eq!(intl::locale_compare("e\u{301}", "é"), Ordering::Equal);
    assert_eq!(intl::locale_compare("", ""), Ordering::Equal);
    assert_eq!(intl::locale_compare("item10", "item2"), Ordering::Less);
}

#[test]
fn graphemes_match_node() {
    let mut failures = Vec::new();
    for case in SEGMENTS {
        let got: Vec<(usize, &str)> = intl::graphemes(case.text)
            .iter()
            .map(|s| (s.index, s.segment))
            .collect();
        if got != case.graphemes {
            failures.push(format!(
                "{:?}:\n  expected {:?}\n  got      {:?}",
                case.text, case.graphemes, got
            ));
        }
        assert_eq!(intl::grapheme_count(case.text), case.graphemes.len(), "{:?}", case.text);
    }
    assert!(
        failures.is_empty(),
        "{} mismatches:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

type WordSegments = &'static [(usize, &'static str, bool)];

/// PORT: ICU4C and ICU4X segment some Japanese kana runs differently with the same CJ
/// dictionary (different best-path heuristics). These are the only accepted word divergences.
const KNOWN_WORD_DIVERGENCES: &[(&str, WordSegments)] = &[
    (
        "カタカナとひらがな、漢字",
        &[
            (0, "カタカナ", true),
            (4, "と", true),
            (5, "ひらが", true),
            (8, "な", true),
            (9, "、", false),
            (10, "漢字", true),
        ],
    ),
    ("ｶﾀｶﾅﾞ", &[(0, "ｶﾀｶﾅ\u{ff9e}", true)]),
];

#[test]
fn words_match_node() {
    let mut failures = Vec::new();
    for case in SEGMENTS {
        if let Some((_, ours)) = KNOWN_WORD_DIVERGENCES.iter().find(|(t, _)| *t == case.text) {
            let got: Vec<(usize, &str, bool)> = intl::words(case.text)
                .iter()
                .map(|s| (s.index, s.segment, s.is_word_like.unwrap()))
                .collect();
            assert_eq!(&got, ours, "known divergence changed for {:?}", case.text);
            continue;
        }
        let got: Vec<(usize, &str, bool)> = intl::words(case.text)
            .iter()
            .map(|s| {
                (
                    s.index,
                    s.segment,
                    s.is_word_like.expect("word segments carry isWordLike"),
                )
            })
            .collect();
        if got != case.words {
            failures.push(format!(
                "{:?}:\n  expected {:?}\n  got      {:?}",
                case.text, case.words, got
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} mismatches:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn trailing_combining_marks_keep_word_like_status() {
    // ICU4X reports these as not word-like when text follows; Node (ICU4C) does not.
    for (text, expected) in [
        ("e\u{301} x", vec![true, false, true]),
        ("नमस्ते दुनिया", vec![true, false, true]),
        ("1\u{20e3} a", vec![true, false, true]),
        ("a\u{ad} b", vec![true, false, true]),
        ("👍🏽 x", vec![false, false, true]),
        ("#\u{fe0f}\u{20e3} x", vec![false, false, true]),
        ("  x", vec![false, true]),
    ] {
        let got: Vec<bool> = intl::words(text).iter().map(|s| s.is_word_like.unwrap()).collect();
        assert_eq!(got, expected, "{text:?}");
    }
}

#[test]
fn segments_carry_byte_and_utf16_offsets() {
    let s = "a😀é b";
    let g = intl::graphemes(s);
    let offsets: Vec<(usize, usize, Option<bool>)> =
        g.iter().map(|x| (x.index, x.byte_index, x.is_word_like)).collect();
    assert_eq!(
        offsets,
        vec![(0, 0, None), (1, 1, None), (3, 5, None), (4, 7, None), (5, 8, None)]
    );
    for seg in intl::words(s) {
        assert_eq!(&s[seg.byte_index..seg.byte_index + seg.segment.len()], seg.segment);
    }
    assert!(intl::graphemes("").is_empty());
    assert!(intl::words("").is_empty());
}

#[test]
fn dates_match_node_in_fixed_offset_zones() {
    let mut failures = Vec::new();
    for &(tz, offset_minutes, cases) in DATES {
        let zone = FixedOffset::east_opt(offset_minutes * 60).expect("valid offset");
        for case in cases {
            let got = (
                intl::date_to_locale_string_in(case.ms, &zone),
                intl::date_to_locale_time_string_in(case.ms, false, &zone),
                intl::date_to_locale_time_string_in(case.ms, true, &zone),
            );
            let expected = (
                case.date_time.to_string(),
                case.time.to_string(),
                case.time_2digit.to_string(),
            );
            if got != expected {
                failures.push(format!("TZ={tz} ms={}: expected {expected:?}, got {got:?}", case.ms));
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} mismatches:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn local_zone_functions_use_chrono_local() {
    for ms in [0, 1_790_899_503_000, -62_135_596_800_000, 8_640_000_000_000_001] {
        assert_eq!(
            intl::date_to_locale_string(ms),
            intl::date_to_locale_string_in(ms, &chrono::Local)
        );
        assert_eq!(
            intl::date_to_locale_time_string(ms, true),
            intl::date_to_locale_time_string_in(ms, true, &chrono::Local)
        );
    }
}
